import labels_mspre as B
from labels_mspre import N, th, cs, tc, pct, R, HC, MV, GT, rng, KHS, GH, GC, TERT_SD, LABEL, UNIT, EXPECT, GROUPS
g = GT["2017"]; h = GT["2019"]
TITLE = "Early Metabolic Risk Is Modestly Higher in Less-Educated Districts of South Korea"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower()
KEYWORDS = ["metabolic syndrome", "educational status", "health equity", "small-area analysis", "Republic of Korea"]
RUNNING = "Education and early metabolic risk in Korea"
YRS = ("2019", "2020", "2021", "2022", "2023", "2024")
lo_r, hi_r = min(R[y] for y in YRS), max(R[y] for y in YRS)

ABSTRACT = [
("Objectives", "To describe how adults with 1 or 2 metabolic syndrome components, an early stage of metabolic risk, are distributed across districts and which district characteristics accompany this distribution."),
("Methods", f"Ecological panel of all {N['n_districts']} districts of South Korea, 2019-2024, using national health screening statistics ({N['cases_total_m']:.1f} million early-risk judgments among {N['exam_total_m']:.1f} million examinees). Expected counts were standardized for sex and age. Bayesian spatiotemporal negative binomial models related counts to 11 prespecified district characteristics."),
("Results", f"The early-risk group made up {lo_r:.1f}% to {hi_r:.1f}% of examinees each year. District ratios differed by about 9% between the 10th and 90th percentiles, with persistent excesses in southern rural counties and deficits in the capital region. Only the share of adults with a college degree was consistently associated (rate ratio per SD = {N['main']['tertiary'][0]:.3f}; 95% credible interval = {N['main']['tertiary'][1]:.3f}, {N['main']['tertiary'][2]:.3f}), across all sensitivity analyses."),
("Conclusions", "Early metabolic risk among Korean screening examinees follows a small but stable education gradient across districts."),
("Public Health Implications", "Prevention aimed at the stage before the metabolic syndrome could prioritize districts with fewer college-educated adults."),
]

INTRO = [
"The metabolic syndrome, the co-occurrence of at least 3 of 5 components (abdominal obesity, raised blood pressure, raised fasting glucose, raised triglycerides, and low high-density lipoprotein [HDL] cholesterol), is associated with higher risks of cardiovascular disease, diabetes, and death [@alberti2009harmonizing; @ford2005risks]. Risk does not begin at the threshold of 3 components: in nationwide Korean screening cohorts, cumulative exposure to the syndrome and its components was associated with myocardial infarction and stroke [@lee2020exposure]. Adults with 1 or 2 components are therefore a group in which prevention may still limit the accumulation of risk.",
"In South Korea this early-risk group is large. The national general health screening program reports each examinee's number of components, and nearly half of examinees have 1 or 2 of them [@web:kosis2026screening]. Studies of the geography of metabolic risk have mapped the full syndrome or its separate components [@noubiap2022geographic; @han2021regional; @lee2025regional]; the early-risk state, where the next cases form, has seldom been mapped.",
"Socioeconomic position, and education in particular, is among the most consistent correlates of the metabolic syndrome. A meta-analysis found higher odds of the syndrome with lower socioeconomic position [@blanquet2019socio], and Korean studies found an inverse educational gradient, strongest in women and partly explained by obesity [@kim2005educational; @ko2015obesity; @kim2018educational]. Whether this gradient appears at the level of districts, where prevention programs are planned and funded, and whether it is already visible at the stage of 1 or 2 components, is unknown. Districts also differ in behaviors that plausibly shape early metabolic risk, such as weight management, smoking, and drinking [@sun2012active], and in the reach of screening itself [@yang2013regional; @kim2023regional].",
"This study used 6 years of national screening statistics to ask how examinees with 1 or 2 metabolic syndrome components are distributed across Korean districts and which district characteristics, defined before model fitting, are associated with that distribution once age, sex, and spatial structure are accounted for.",
]

METHODS = [
("Study Design and Data",
 f"This ecological panel study covered all {N['n_districts']} districts (si, gun, and gu) of South Korea and followed the STROBE statement [@vonelm2007strengthening]. Outcome counts came from the national general health screening statistics of the National Health Insurance Service, published on the Korean Statistical Information Service [@web:kosis2026screening]; the program offers screening to insured adults every 2 years [@seong2017cohort]. District covariates came from the Community Health Survey [@kang2015korea], the census and public assistance statistics [@web:kosis2026], and resident registration [@web:mois2026population]. For 2019-2024, all 1,368 district-year counts matched the source table, and Sejong (6 district-years) was taken from its provincial row; district totals equaled national totals in every year (Table S1, available as a supplement to the online version of this article). For 2013-2017, Sejong and Bucheon in 2016 (the sum of its 3 former districts) were filled from the source table. Fixed adjustments and negative-control exposures came from the local indicators of the Korean Statistical Information Service [@web:kosis2026]. All inputs were read from a fixed, read-only copy of the compiled database. The study used only published aggregate statistics."),
("Outcome",
 "The outcome was the annual number of examinees in the early-risk group, defined in the screening statistics as examinees with 1 or 2 of 5 components: waist circumference of at least 90 cm in men or 85 cm in women [@lee2007appropriate]; blood pressure of at least 130/85 mm Hg or antihypertensive treatment; fasting glucose of at least 100 mg/dL or glucose-lowering treatment; triglycerides of at least 150 mg/dL; and HDL cholesterol below 40 mg/dL in men or 50 mg/dL in women [@alberti2009harmonizing]. The denominator was the number of examinees assessed in the same district and year, so the quantity estimated is a prevalence among examinees, not among all residents. Examinees with 3 to 5 components, who meet the metabolic syndrome definition, and examinees with none form the complementary cells of the same table.",
 f"Before modeling, national counts were compared with the 5 component prevalences year by year (Table S2). The 2018 table covered {N['gate_exam_2018_m']:.1f} million examinees, about one third of adjacent years, and was excluded. Between 2017 and 2019, high triglycerides fell from {g['tg_pct']:.1f}% to {h['tg_pct']:.1f}% and low HDL cholesterol from {g['hdl_pct']:.1f}% to {h['hdl_pct']:.1f}%, whereas other components changed by less than 3 percentage points; this coincided with the 2018 lengthening of the lipid-testing interval [@web:yonhap2023screening]. The main analysis therefore used 2019-2024, an auxiliary analysis used 2013-2017, and no model spanned the discontinuity. Because examinees without a lipid test in a given year cannot be counted for the lipid components, this restriction kept the outcome definition constant within each period. Tables before 2013 were not published."),
("Expected Counts",
 "Expected counts were obtained by indirect standardization [@inskip1983methods] with national early-risk rates for 2 sexes and 15 age groups in each year. Because district examinee counts by age are not published, each district's examinee age structure was approximated by its resident population by sex and age multiplied by the national age-specific examinee proportion, then rescaled to the observed district examinee count. Expected counts were rescaled to the national total each year, so the standardized ratio compares each district with the national level of the same year. Sensitivity analyses used crude expected counts and population-based expected counts (residents multiplied by national cases per resident), which change the estimand to judgments per resident but do not correct selection into screening. Indirect standardization assumes that national age-specific attendance approximates attendance within each district and sex."),
("District Characteristics",
 f"Eleven characteristics in 4 groups were defined before fitting, each with an expected direction (Table S3): nutrition label use and weight control attempts (expected to lower counts); perceived stress and depressive mood (expected to raise counts); self-reported obesity, high-risk drinking, and current smoking (expected to raise counts); and the share of adults with a college or university degree in the census (tertiary-educated share; expected to lower counts) [@blanquet2019socio; @kim2005educational], the public assistance recipient rate and the share of single-person households (expected to raise counts), and screening uptake (expected to lower counts). All models included 5 fixed adjustments: urban population share, physicians per 1000 residents, sex ratio, fiscal autonomy, and the share aged 80 years or older. Characteristics were standardized to 1 SD of district-years; 1 SD of the tertiary-educated share was {TERT_SD:.1f} percentage points. Survey items not collected in 2019 were filled with the district mean of later years, and missing values for Sejong in 2 survey items with the yearly median. Covariate inputs were audited for years in which every district was zero, structural zeros, boundary changes, and jumps of more than 30% in national means; none required exclusion. Hit-and-run crashes, a traffic culture index, and fires served as negative-control exposures [@lipsitch2010negative].",
 "An earlier covariate set centered on physical activity showed no credible association and, under a rule set in advance for this analysis, was replaced by the present outcome-specific set, which was written to a file and hashed before fitting. The analysis is therefore exploratory."),
("Statistical Analysis",
 "Counts were modeled with negative binomial likelihoods, log expected counts as offsets, a Besag-York-Mollié 2 district effect on the contiguity graph [@besag1991bayesian; @riebler2016intuitive], and random-walk and unstructured year effects, fitted with integrated nested Laplace approximation [@rue2009approximate] in R 4.6.0 with INLA 25.10.19 and a single thread; the principal model was fitted twice to confirm reproducibility, and fit was compared with the widely applicable information criterion. An association was called credible when the 95% credible interval (CrI) of the rate ratio (RR) per 1 SD excluded 1.",
 "Robustness was assessed in 5 ways: (1) 200 models with random subsets of the 11 characteristics [@steegen2016increasing]; (2) Knorr-Held type II to IV space-time interactions [@knorrheld2000bayesian], of which the type III and IV models completed only with a specified starting value for the interaction precision; (3) Spatial+ [@dupont2022spatial] and restricted spatial regression, which can understate uncertainty [@hodges2010adding; @hanks2015restricted]; (4) 37 alternative analyses changing 1 element at a time, including lags, omission of each province and year, alternative neighbor graphs, and separation of between- and within-district components [@bell2015explaining]; and (5) refitting to 2 comparison outcomes from the same screening tables (the metabolic syndrome and untreated dyslipidemia), to 2013-2017, and with the alternative expected counts. E-values were computed for credible associations [@vanderweele2017sensitivity].",
 "Spatial clustering of observed log standardized ratios was described with Moran's I and the local Getis-Ord Gi* statistic [@getis1992analysis], and temporal persistence of district ranks with Kendall's W. Gi* was used descriptively without adjustment for multiple testing. Residual spatial autocorrelation was tested 2-sided with 999 permutations and reported as observed I, expected I (−1/[n−1]), and P value; an observed I below its expectation with P < .05 was read as possible overfitting of local spatial structure by the district effect. Results are interpreted at the district level, not as individual associations [@morgenstern1995ecologic]."),
]

RESULTS = [
("Early-Risk Group and Its Geography",
 f"The analysis covered {th(N['n_rows'])} district-years with {N['cases_total_m']:.1f} million early-risk judgments among {N['exam_total_m']:.1f} million examinees (Table 1). The early-risk group made up {R['2019']:.1f}% of examinees in 2019 and {R['2024']:.1f}% in 2024, while the share meeting the metabolic syndrome definition rose from {GT['2019']['mets_pct']:.1f}% to {GT['2024']['mets_pct']:.1f}% (Figure 1B).",
 f"District standardized ratios for 2019-2024 ranged from {N['sir_min']:.2f} to {N['sir_max']:.2f}; the 10th and 90th percentiles were {N['sir_p10']:.3f} and {N['sir_p90']:.3f}, a ratio of {N['p90p10']:.2f}, and crude district proportions ranged from {N['crude_p10']:.1f}% to {N['crude_p90']:.1f}% between the same percentiles. Ratios were spatially clustered (Moran's I {N['moran_min']:.2f}-{N['moran_max']:.2f} by year; <i>P</i> = .001 in every year), and district ranks were stable (Kendall's W = {N['kendall_w']:.2f}; Spearman ρ between 2019 and 2024 = {N['rho_2019_2024']:.2f}). Gi* identified {N['gi_hot']} hot spots, {GH.get('Jeonnam', 0)} in Jeonnam, {GH.get('Gyeongbuk', 0)} in Gyeongbuk, and {GH.get('Gyeongnam', 0)} in Gyeongnam, of which {N['gi_hot_gun']} were rural counties, and {N['gi_cold']} cold spots, {GC.get('Seoul', 0)} in Seoul and {GC.get('Gyeonggi', 0)} in Gyeonggi (Figure 1A). Median tertiary-educated shares were {HC['hot']['tert']:.1f}% in hot spots, {HC['other']['tert']:.1f}% in other districts, and {HC['cold']['tert']:.1f}% in cold spots, and median shares aged 80 years or older were {HC['hot']['p80']:.1f}%, {HC['other']['p80']:.1f}%, and {HC['cold']['p80']:.1f}% (Figure 1C). Across districts, the standardized ratio was inversely correlated with the tertiary-educated share (ρ = {N['rho_sir_tert']:.2f}).",
 f"District ranks correlated with those for untreated dyslipidemia (ρ = {N['rho_lipt'][0]:.2f}) and weakly with those for the metabolic syndrome (ρ = {N['rho_mets'][0]:.2f}) in the same years. Ranks from 2013-2017 correlated with those from 2019-2024 (ρ = {N['rho_aux_main']:.2f}); the year-to-year rank correlation was {N['rho_1617']:.2f} between 2016 and 2017 and {N['rho_1719']:.2f} between 2017 and 2019, across the change in the lipid-testing interval."),
("District Characteristics",
 f"The negative binomial likelihood fitted better than the Poisson likelihood (widely applicable information criterion {th(N['waic_forced'], 1)} vs {th(N['waic_forced_pois'], 1)} for the model with adjustments only). Adding the 11 characteristics changed the criterion to {th(N['waic_main'], 1)}, and the Knorr-Held type II interaction lowered it to {th(N['KH_typeII_waic'], 1)}. Of the 11 characteristics, only the tertiary-educated share had a credible association: each 1 SD higher share was associated with {pct(1 - N['main']['tertiary'][0])} fewer early-risk examinees than expected ({cs('tertiary')}; Table 2). Weight control attempts had an upper limit at 1.000 ({cs('weight_control')}), and the other 9 characteristics had intervals including 1. Among adjustments, the share aged 80 years or older was inversely associated ({cs('pop80')}).",
 f"The tertiary-educated share was credible in all {MV['tertiary'][2]} subset models that contained it and in all {N['ret']['tertiary'][1]} alternative analyses (RRs {N['ret']['tertiary'][2]:.3f}-{N['ret']['tertiary'][3]:.3f}). It ranged from {rng('tertiary', KHS)} across Knorr-Held models and was {tc(None, N['D1_spatial_plus']['tertiary'])} with Spatial+ and {tc(None, N['RSR']['tertiary'])} with restricted spatial regression, and was {tc(None, N['C4_sido_year_iid']['tertiary'])} with province-by-year effects and {tc(None, N['E1_lag1']['tertiary'])} with covariates lagged by 1 year (Figure 2). Its between-district component was {tc(None, N['between'])} and its within-district component {tc(None, N['within'])}. The association was {tc(None, N['win']['tertiary|W1_2019-21'])} in 2019-2021 and {tc(None, N['win']['tertiary|W2_2022-24'])} in 2022-2024, and by region it was {tc(None, N['reg']['tertiary_educated_share|Capital'])} in the capital region, {tc(None, N['reg']['tertiary_educated_share|Yeongnam'])} in Yeongnam, {tc(None, N['reg']['tertiary_educated_share|Honam'])} in Honam, {tc(None, N['reg']['tertiary_educated_share|Chungcheong'])} in Chungcheong, and {tc(None, N['reg']['tertiary_educated_share|Gangwon_Jeju'])} in Gangwon and Jeju. With population-based expected counts it was {tc(None, N['sp']['tertiary'])}, with crude expected counts {tc(None, N['sc']['tertiary'])}, and in 2013-2017 {tc(None, N['aux']['tertiary'])} (Table S4). The E-value was {N['evalue']['tertiary'][0]:.2f} (CrI limit {N['evalue']['tertiary'][1]:.2f}).",
 f"Weight control attempts were credible in {pct(MV['weight_control'][0])} of subset models and public assistance recipients in {pct(MV['basic_livelihood'][0])}; no other characteristic was credible in more than {pct(MV['smoking'][0])} (Table S5). With restricted spatial regression, 5 further variables had intervals excluding 1, all with RRs between {min(N['RSR'][k][0] for k in ('weight_control', 'stress', 'single_household', 'screening_uptake', 'urban')):.3f} and {max(N['RSR'][k][0] for k in ('weight_control', 'stress', 'single_household', 'screening_uptake', 'urban')):.3f}. With population-based expected counts, screening uptake was positively associated ({cs('screening_uptake', 'sp')})."),
("Comparison Outcomes, Negative Controls, and Model Checks",
 f"The tertiary-educated share was associated with fewer examinees meeting the metabolic syndrome definition ({cs(None, N['nco']['METSC|tertiary'])}) and with more examinees with untreated dyslipidemia ({cs(None, N['nco']['LIPTC6|tertiary'])}). Negative-control exposures had RRs of {tc(None, N['nc']['hit_and_run_rate'])} (hit-and-run crashes), {tc(None, N['nc']['fires_per_10000'])} (fires), and {tc(None, N['nc']['traffic_culture_index'])} (traffic culture index).",
 f"Posterior predictive 95% intervals contained {N['ppc95']:.1f}% of observed counts (probability integral transform Kolmogorov-Smirnov <i>P</i> = {('%.2f' % N['pit_p']).lstrip('0')}), and a model fitted without 2024 covered {N['oos_cov']:.1f}% of 2024 district counts with a median absolute error of {N['oos_mape']:.1f}%. The structured district effect accounted for {N['vp']['spatial_structured']:.0f}% of the variance of the linear predictor, fixed effects for {N['vp']['fixed_covariates']:.1f}%, and year effects for less than 1%. Residual Moran's I was {N['resid_moran']:.3f} (expected {N['rm_expected']:.4f}; 2-sided <i>P</i> = {('%.3f' % N['resid_moran_p']).lstrip('0')}) and was below its expectation in every specification with a structured district effect, compared with {N['rm_spec']['no_spatial'][0]:.3f} without a district effect and {N['rm_spec']['iid_district'][0]:.3f} with an independent district effect (Table S6). A second fit of the principal model reproduced every RR to 3 decimal places."),
]

DISCUSSION = [
("### Principal Findings",),
"Nearly half of Korean screening examinees had 1 or 2 metabolic syndrome components, and the share of this early-risk group differed modestly but persistently among districts. Districts in the southern provinces, many of them rural counties with older populations, had more early-risk examinees than expected, and districts of the capital region had fewer. Of the characteristics examined, only the share of adults with tertiary education was consistently associated, inversely, across covariate subsets, space-time interactions, spatial-confounding methods, alternative expected counts, and the earlier period. The association was estimated mainly from differences between districts. The relative differences are small, as expected for a state that nearly half of examinees occupy; the value of the map lies in its persistence, because the same districts ranked high year after year. Rank agreement was weaker across the change in the lipid-testing schedule than within each period, so persistent differences in attendance or lipid testing cannot be excluded as part of the pattern.",
("### Education and Early Metabolic Risk",),
"The direction agrees with individual-level evidence that less education accompanies more metabolic syndrome in Korea and across countries [@kim2005educational; @kim2018educational; @blanquet2019socio]. These results add that the gradient is already visible at the district level before the syndrome threshold is crossed. Individual studies attributed much of the gradient to obesity and found it mainly in women [@ko2015obesity; @kim2018educational]; this sex-pooled district analysis cannot test sex differences, and district obesity, drinking, smoking, and stress did not account for the association. Access to health information, food environments, occupation, and care are other plausible pathways that this design could not test.",
"The comparison outcomes help to interpret the gradient. Districts with more graduates had fewer examinees with the syndrome as well as fewer in the early-risk group, so higher education corresponded to more examinees with no component at all. These districts had more examinees with untreated dyslipidemia, an outcome that depends on being tested and not yet treated. The gradient therefore appears specific to the metabolic profile of examinees rather than to any screening judgment. Its weakening with Spatial+ and the small E-value indicate that part of it is plausibly shared with unmeasured regional features, such as occupation and income, that follow the same urban-rural lines.",
("### Other Characteristics",),
"Weight management, psychosocial strain, risk behaviors, deprivation, single-person households, and screening uptake showed no consistent association. Survey measures are district estimates with limited between-district variation, so absence of association means insufficient evidence at the district level, not evidence of no effect for individuals [@morgenstern1995ecologic]. Restricted spatial regression made several characteristics credible, but this method can understate uncertainty [@hanks2015restricted], and these characteristics were not credible in other models. The intervals for weight control attempts lay close to the null and excluded it only in some models, compatible with a small but not a consistent association. The inverse association with the share of the oldest residents, an adjustment variable, may reflect survivor selection, selective attendance, or residual age confounding. Screening uptake was positively associated only when expected counts were based on residents, as expected because more attendance produces more judgments per resident.",
("### Strengths and Limitations",),
"The study used complete national screening statistics for all districts, checked the composition of the outcome before modeling, restricted the main analysis to a period with a constant testing schedule, used each year's national rates for expected counts, fixed the covariate set before fitting, and reported every spatial-confounding and sensitivity analysis.",
"First, the outcome is a prevalence among examinees, and attendance differs by district and socioeconomic position [@yang2013regional; @kim2023regional]. Second, district examinee age structure was approximated from resident population and national attendance, and because education differs strongly by birth cohort, residual confounding by age is possible. Third, under the current lipid-testing interval some examinees were not tested for lipids in the year of judgment. Fourth, both sexes were pooled. Fifth, survey covariates are district estimates with sampling error, and obesity estimates for the first year were filled from later years. Sixth, residual spatial autocorrelation below its expectation suggests that the district effect may overfit local structure, so district ratios are best read as rankings and clusters. Seventh, the covariate set replaced an earlier set, so the finding is exploratory. Finally, the design is ecological, and the associations describe districts, not individuals.",
]

PHI = [
"Adults with 1 or 2 metabolic syndrome components are a large population in which prevention can still act before the syndrome develops. In South Korea, this early-risk group is modestly but persistently more common in districts with fewer college-educated adults, many of them rural counties of the southern provinces. Local health centers in these districts could give priority to lifestyle counseling and follow-up of borderline screening results, and national programs could monitor the education gradient at this early stage as a marker of emerging metabolic inequity. Because relative differences are small and absolute numbers are larger in populous urban districts, such targeting should complement, not replace, population-wide prevention. Individual-level longitudinal data are needed to test whether education, or the conditions that accompany it, shapes the transition from early metabolic risk to the full syndrome.",
]

